using System.Diagnostics;
using System.IO.Pipes;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using Playhub.StoreLibrary;

var root = Path.Combine(Path.GetTempPath(), "Playhub-StoreClientPolicy-" + Guid.NewGuid().ToString("N"));
var app = Path.Combine(root,"app"); var bundle=Path.Combine(app,"StoreLibrary"); var decky=Path.Combine(root,"homebrew","services");
Directory.CreateDirectory(bundle);Directory.CreateDirectory(decky);
var source=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../Playhub.StoreHost"));
foreach(var name in new[]{"Playhub.exe","Playhub.GameSession.exe","Playhub.XboxSession.exe"})File.WriteAllText(Path.Combine(app,name),"owned inert image "+name);
foreach(var name in new[]{"PluginLoader.exe","PluginLoader_noconsole.exe"})File.WriteAllText(Path.Combine(decky,name),"owned inert loader "+name);
File.WriteAllText(Path.Combine(bundle,"Playhub.StoreHost.exe"),"inert manifest host");
foreach(var name in new[]{"legendary_windows_x64.exe","gogdl_windows_x86_64.exe"})File.Copy(Path.Combine(source,"Runtime",name),Path.Combine(bundle,name));
var script=Path.Combine(source,"WriteStoreRuntimeManifest.ps1");int checks=0;
void Check(bool condition,string message){if(!condition)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}
void Denied(Action action,string message){try{action();}catch(Exception e)when(e is StoreOperationException or InvalidOperationException or KeyNotFoundException){Check(true,message);return;}throw new Exception(message);}
async Task<int> WriteManifest(){string Q(string value)=>"'"+value.Replace("'","''")+"'";var text=$"& {Q(script)} -BundleDirectory {Q(bundle)} -AppDirectory {Q(app)} -DeckyBinaryPaths @({Q(Path.Combine(decky,"PluginLoader.exe"))},{Q(Path.Combine(decky,"PluginLoader_noconsole.exe"))})";var start=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"WindowsPowerShell/v1.0/powershell.exe")){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var arg in new[]{"-NoProfile","-NonInteractive","-EncodedCommand",Convert.ToBase64String(Encoding.Unicode.GetBytes(text))})start.ArgumentList.Add(arg);using var child=Process.Start(start)!;var stdout=child.StandardOutput.ReadToEndAsync();var stderr=child.StandardError.ReadToEndAsync();await child.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(30));File.WriteAllText(Path.Combine(root,"writer-output.txt"),await stdout+await stderr);return child.ExitCode;}
Check(await WriteManifest()==0,"actual finalization script accepts app, GameSession, sidecar and two exact Decky loader images");
using var doc=JsonDocument.Parse(File.ReadAllText(Path.Combine(bundle,"store-runtime.json")));
var clients=StoreRuntimeClientPolicy.Read(doc.RootElement.GetProperty("allowedClients"),app,decky);
Check(clients.Length==5,"finalized candidate has five pinned clients");var helper=clients.Single(client=>client.Kind=="xbox-companion");
Check(helper.Path==Path.Combine(app,"Playhub.XboxSession.exe")&&helper.Hash==Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(helper.Path))),"sidecar is bound to exact app-relative path and actual SHA256");
Check(StoreRuntimeClientPolicy.IsAuthorizedImage(clients,helper.Path),"actual pinned sidecar image admitted");
Check(!StoreRuntimeClientPolicy.IsAuthorizedImage(clients.Where(client=>client.Kind!="xbox-companion").ToArray(),helper.Path),"legacy four-client manifest reproduces the real sidecar admission failure");
var original=File.ReadAllBytes(helper.Path);File.AppendAllText(helper.Path,"tampered");Check(!StoreRuntimeClientPolicy.IsAuthorizedImage(clients,helper.Path),"changed sidecar bytes cannot reuse pinned admission");File.WriteAllBytes(helper.Path,original);
var other=Path.Combine(root,"Playhub.XboxSession.exe");File.WriteAllBytes(other,original);Check(!StoreRuntimeClientPolicy.IsAuthorizedImage(clients,other),"same helper name and bytes outside exact installation path are refused");
Check(StoreRuntimeClientPolicy.AllowsMethod(clients,helper.Path,"launch-descriptor"),"companion allows only its read-only broker launch descriptor");
string[] denied={"snapshot","downloads","connect-begin","connect-complete","disconnect","refresh","prepare","prepare-parent","directories","enqueue","control","clear-completed","prepare-launch","steam-register","steam-unregister","steam-activity","quiesce","xbox-account-owned","xbox-account-open-owned","prepare-uninstall","uninstall","ui-install-request","ui-install-take"};
foreach(var method in denied)Check(!StoreRuntimeClientPolicy.AllowsMethod(clients,helper.Path,method),"companion policy refuses "+method);
foreach(var image in clients.Where(client=>client.Kind!="xbox-companion"))Check(StoreRuntimeClientPolicy.AllowsMethod(clients,image.Path,"refresh"),"existing app/Decky client method policy stays unchanged: "+Path.GetFileName(image.Path));
foreach(var method in new[]{"prepare","prepare-parent","enqueue","control","cancel-cleanup","remove-history","windows-install-dismiss","prepare-uninstall","uninstall","ui-install-request","prepare-launch","steam-adopt-import","steam-repair-missing"})
    Check(!StoreRuntimeClientPolicy.AllowsMethod(clients,Path.Combine(app,"Playhub.exe"),method),"desktop app cannot install or manage games: "+method);
foreach(var method in new[]{"snapshot","connect-begin","connect-complete","disconnect","refresh","xbox-account-begin","xbox-account-poll","xbox-account-cancel","steam-sync-request","steam-sync-status"})
    Check(StoreRuntimeClientPolicy.AllowsMethod(clients,Path.Combine(app,"Playhub.exe"),method),"desktop access and migration remain available: "+method);
Check(StoreRuntimeClientPolicy.AllowsMethod(clients,Path.Combine(decky,"PluginLoader.exe"),"enqueue"),"Big Picture retains installation capability");
var clientJson=JsonNode.Parse(doc.RootElement.GetProperty("allowedClients").GetRawText())!.AsArray();
foreach(var change in new[]{"broaden","missing","wrong-kind","wrong-path","duplicate"}){var changed=JsonNode.Parse(clientJson.ToJsonString())!.AsArray();var node=changed.Single(value=>value!["kind"]!.GetValue<string>()=="xbox-companion")!;switch(change){case"broaden":node["methods"]=new JsonArray("launch-descriptor","prepare-launch");break;case"missing":node.AsObject().Remove("methods");break;case"wrong-kind":node["kind"]="app";break;case"wrong-path":node["path"]="Elsewhere/Playhub.XboxSession.exe";break;case"duplicate":changed.Add(JsonNode.Parse(node.ToJsonString()));break;}using var invalid=JsonDocument.Parse(changed.ToJsonString());Denied(()=>StoreRuntimeClientPolicy.Read(invalid.RootElement,app,decky),"malformed/broadened companion manifest is refused: "+change);}
await using(var engine=new StoreQueueEngine([],new StoreInstallFileSystem(),Path.Combine(root,"queue.json"))){var pipeName="Playhub-StoreClientPolicy-"+Guid.NewGuid().ToString("N");using var stop=new CancellationTokenSource();bool pinned=true;string clientImage=helper.Path;int privateRequests=0;var server=new StorePipeServer(engine,_=>pinned,pipeName:pipeName,authorizePrivateLaunch:_=>{privateRequests++;return true;},maintenanceFactory:()=> (Guid.NewGuid(),DateTimeOffset.UtcNow.AddMinutes(1)),authorizeMethod:(_,method)=>StoreRuntimeClientPolicy.AllowsMethod(clients,clientImage,method));var serving=server.RunAsync(stop.Token);
try{async Task<JsonElement> Call(string method){await using var pipe=new NamedPipeClientStream(".",pipeName,PipeDirection.InOut,PipeOptions.Asynchronous);await pipe.ConnectAsync(2000);using var writer=new StreamWriter(pipe,new UTF8Encoding(false),4096,true){AutoFlush=true};using var reader=new StreamReader(pipe,new UTF8Encoding(false),false,4096,true);await writer.WriteLineAsync(JsonSerializer.Serialize(new{protocol=1,id=Guid.NewGuid(),method,args=new{key=new{store="xbox",id="9NBLGGH1ZB7X"}}}));using var reply=JsonDocument.Parse((await reader.ReadLineAsync().WaitAsync(TimeSpan.FromSeconds(3)))!);return reply.RootElement.Clone();}
var allowed=await Call("launch-descriptor");Check(allowed.GetProperty("ok").GetBoolean()&&allowed.GetProperty("data").GetProperty("key").GetProperty("id").GetString()=="9NBLGGH1ZB7X","actual named-pipe server permits the helper launch-descriptor operation");foreach(var method in denied){var reply=await Call(method);Check(!reply.GetProperty("ok").GetBoolean()&&reply.GetProperty("errorCode").GetString()=="client_not_authorized","actual pipe blocks helper before dispatch: "+method);}Check(privateRequests==0,"restricted helper never reaches the private prepare-launch capability");pinned=false;var refused=await Call("launch-descriptor");Check(!refused.GetProperty("ok").GetBoolean()&&refused.GetProperty("errorCode").GetString()=="client_not_authorized","allowed read operation still requires exact pinned process admission");clientImage=Path.Combine(root,"FutureInstaller.exe");var revocation=await Call("quiesce");Check(revocation.GetProperty("ok").GetBoolean()&&revocation.GetProperty("data").GetProperty("accepted").GetBoolean(),"unknown future same-user installer preserves revocation-only quiescence");var foreignRead=await Call("snapshot");Check(!foreignRead.GetProperty("ok").GetBoolean()&&foreignRead.GetProperty("errorCode").GetString()=="client_not_authorized","unknown future installer still cannot read library data");}
finally{stop.Cancel();try{await serving;}catch(OperationCanceledException){}}}
File.Delete(helper.Path);Check(await WriteManifest()!=0,"actual manifest finalization refuses a missing XboxSession sidecar");
Console.WriteLine($"PASS {checks} client admission/method tests; only TEMP fixtures/local named pipes. Evidence {root}");
